from lib import *
S = SS('v84')
steps = [
    step("启动时 Envoy 向控制平面要了什么、什么顺序(我写的最小 ADS 控制平面,gRPC 一条流)。表里各资源类型第一次被请求的先后是 CDS、EDS、LDS、RDS:Envoy 先发 CDS(不带资源名,订阅全部集群),控制平面发出 CDS(version 1,资源 c_a);Envoy 接着请求 EDS(带上集群名 c_a),收到后又请求 LDS(订阅全部监听器),控制平面发出 LDS(version 1,资源 l0);Envoy 再请求 RDS(带上路由配置名 r0),控制平面发出 RDS(version 1)。每个类型收到之后 Envoy 回一条带着刚收到的 version_info 和 nonce 的请求,就是 ACK。从 Envoy 起来到第一个请求成功只用了 0.08 s。", t=tl(S(1)), mark=lidx(S(1), 'LDS', 'RDS'), done=lidx(S(1), 'CDS', 'EDS'), b=bars([['CDS:请求次数(首次 + ACK)', 2, '2'], ['EDS:请求次数', 2, '2'], ['LDS:请求次数', 2, '2'], ['RDS:请求次数', 2, '2']], 2, done=[0, 1], mark=[2, 3]), kv=KV([['请求顺序', 'CDS → EDS → LDS → RDS'], ['资源名', 'CDS / LDS 不带名字,EDS 带 c_a,RDS 带 r0'], ['ACK', '回一条带 version_info 和 nonce 的请求'], ['启动到可用', '0.08 s']], ['请求顺序'])),
    step("NACK。控制平面推一个 Envoy 不接受的监听器(http_filters 里的过滤器名不存在):控制平面发出 LDS version 2,Envoy 立刻回 NACK,version_info 仍然是 1(最后一个被接受的版本),error_detail 是 “Error adding/updating listener(s) l0: Error: terminal filter named envoy.filters.http.nonexistent of type envoy.filters.http.router must be the last filter in a http filter chain.”。NACK 期间通过 Envoy 的 10 个请求全部成功(10 个 A),Envoy 继续用旧监听器。推一个有效更新(version 3):Envoy 回 ACK,version_info 变成 3,之后 5 个请求也全部成功。", t=tl(S(2)), mark=lidx(S(2), 'NACK'), done=lidx(S(2), '发出   | 3', '请求   | 3'), b=bars([['NACK 期间成功的请求', 10, '10 / 10'], ['有效更新之后成功的请求', 5, '5 / 5'], ['NACK 时的 version_info', 1, '1(上一个被接受的版本)'], ['被 ACK 的新 version_info', 3, '3']], 10, done=[0, 1], mark=[2], cur=[3]), kv=KV([['坏配置', 'Envoy 回 NACK,附带 error_detail'], ['NACK 之后', '继续用旧配置,10 / 10 个请求成功'], ['有效更新', 'ACK,version_info = 3']], ['坏配置'])),
    step("推送到流量切换的延迟(客户端每 2 ms 发一个请求,各 15 次)。EDS 更新(c_a 的端点从 A 换成 B):从控制平面调用 set 到客户端第一次收到 B,中位数 1.4 ms,最小 1.0 ms,最大 9.9 ms。RDS 更新(路由从 c_a 改到 c_b):中位数 0.7 ms,最小 0.6 ms,最大 4.7 ms。新集群没有端点的窗口:路由改到新集群 c_c 但它的 EDS 延迟 1.0 s 才推:前 1 s 里的 67 个请求全部是 HTTP 503;EDS 在第 1007 ms 推出,第一次收到 B 的响应在 1014 ms。", t=tl(S(3)), mark=lidx(S(3), '(c)新集群没有端点'), done=lidx(S(3), '(a)EDS 更新', '(b)RDS 更新'), b=bars([['EDS 更新:中位数 ms', 1.4, '1.4'], ['RDS 更新:中位数 ms', 0.7, '0.7'], ['EDS 更新:最大 ms', 9.9, '9.9'], ['新集群无端点:503 个数', 67, '67(1 s 内)']], 67, done=[0, 1], cur=[2], mark=[3]), kv=KV([['EDS 更新到切换', '中位数 1.4 ms(1.0~9.9)'], ['RDS 更新到切换', '中位数 0.7 ms(0.6~4.7)'], ['路由指向没有端点的新集群', '503 持续到 EDS 到位']], ['路由指向没有端点的新集群'])),
    step("控制平面断开。停掉 ADS 的 gRPC 服务器,数据平面独自运行 6 s,期间 102 个请求全部成功(102 个 B),Envoy 继续用最后一份配置。控制平面在原来的端口重启之后,Envoy 用了 11.6 s 重新建立 ADS 流(另一次运行是 1.3 s,重连时间有明显波动),然后重新发来 CDS(version 3)、EDS(version 33,资源 c_c、c_b、c_a)、LDS(version 3)、RDS(version 32,资源 r0)的请求。重连之后推送更新(c_a 的端点换成 B),后面 5 个请求全部是 B,更新照常生效。", t=tl(S(4)), mark=lidx(S(4), '重新连上之后'), done=lidx(S(4), '控制平面停了 6 s'), b=bars([['控制平面断开期间成功的请求', 102, '102 / 102'], ['重新连上用时 s', 11.6, '11.6(另一次 1.3)'], ['重连后更新生效的请求', 5, '5 / 5']], 102, done=[0, 2], mark=[1]), kv=KV([['控制平面停了 6 s', '102 / 102 个请求成功'], ['重新连上', '11.6 s(另一次运行 1.3 s)'], ['重连后', '重新订阅并拿到当前版本,更新生效']], ['重新连上'])),
]
